<script setup lang="ts">
import { h,onMounted,reactive,ref } from 'vue';import { NButton,NImage,NPopconfirm,NSpace,NSwitch } from 'naive-ui';import type { DataTableColumns } from 'naive-ui';
import NoticeUserSelect from '@/components/notice-user-select.vue';
import ImageUpload from '@/components/image-upload/index.vue';import { createNoticeCategory,deleteNoticeCategory,fetchNoticeCategories,updateNoticeCategory } from '@/service/api';import { mediaUrl } from '@/utils/service';
defineOptions({name:'NoticeCategory'});const rows=ref<Api.P3.Category[]>([]),loading=ref(false),open=ref(false),editing=ref(false);const form=reactive<Partial<Api.P3.Category>>({name:'',iconUrl:'',sortOrder:0,enabled:true,recipientPolicy:'all',recipientUserIds:[]});
async function load(){loading.value=true;try{const r=await fetchNoticeCategories();if(r.data)rows.value=r.data;}finally{loading.value=false;}}
function edit(row?:Api.P3.Category){editing.value=!!row;Object.assign(form,row||{id:undefined,name:'',iconUrl:'',sortOrder:0,enabled:true,recipientPolicy:'all',recipientUserIds:[]});open.value=true;}
async function save(){if(!form.name?.trim()){window.$message?.warning('请输入分类名称');return;}if(form.recipientPolicy==='users'&&!form.recipientUserIds?.length){window.$message?.warning('请选择接收用户');return;}const r=editing.value?await updateNoticeCategory(form):await createNoticeCategory(form);if(!r.error){open.value=false;window.$message?.success('分类已保存');await load();}}
async function toggle(row:Api.P3.Category,value:boolean){await updateNoticeCategory({...row,enabled:value});await load();}
const columns:DataTableColumns<Api.P3.Category>=[{title:'图标',key:'iconUrl',width:90,render:r=>r.iconUrl?h(NImage,{src:mediaUrl(r.iconUrl),width:44,height:44,objectFit:'cover'}):'内置铃铛'},{title:'名称',key:'name'},{title:'接收规则',key:'recipientPolicy',render:r=>({all:'全体用户',users:'指定用户',choose:'发送时选择'}[r.recipientPolicy])},{title:'排序',key:'sortOrder',width:100},{title:'启用',key:'enabled',width:100,render:r=>h(NSwitch,{value:r.enabled,'onUpdate:value':v=>toggle(r,v)})},{title:'操作',key:'op',width:180,render:r=>h(NSpace,{},()=>[h(NButton,{size:'small',onClick:()=>edit(r)},()=> '编辑'),h(NPopconfirm,{onPositiveClick:async()=>{const x=await deleteNoticeCategory(r.id);if(!x.error)await load();}},{trigger:()=>h(NButton,{size:'small',type:'error'},()=> '删除'),default:()=> '仅空分类可以删除，是否继续？'})])}];onMounted(load);
</script>
<template><div><NCard title="通知分类" :bordered="false"><template #header-extra><NButton type="primary" @click="edit()">新增分类</NButton></template><NDataTable :columns="columns" :data="rows" :loading="loading" /></NCard><NModal v-model:show="open" preset="card" :title="editing?'编辑分类':'新增分类'" class="w-600px max-w-95vw"><NForm label-placement="left" label-width="90"><NFormItem label="名称"><NInput v-model:value="form.name" maxlength="20" /></NFormItem><NFormItem label="接收规则"><NSelect v-model:value="form.recipientPolicy" :options="[{label:'固定全体用户',value:'all'},{label:'固定指定用户',value:'users'},{label:'发送时选择',value:'choose'}]" /></NFormItem><NFormItem v-if="form.recipientPolicy==='users'" label="接收用户"><NoticeUserSelect v-model:value="form.recipientUserIds!" /></NFormItem><NFormItem label="图标"><ImageUpload v-model="form.iconUrl!" /></NFormItem><NFormItem label="排序"><NInputNumber v-model:value="form.sortOrder" /></NFormItem><NFormItem label="启用"><NSwitch v-model:value="form.enabled" /></NFormItem></NForm><template #footer><NSpace justify="end"><NButton @click="open=false">取消</NButton><NButton type="primary" @click="save">保存</NButton></NSpace></template></NModal></div></template>
